e'=>'Jouw Verwijzing Coupon Code','Your Referral Coupon:'=>'Jouw verwijzingscoupon:','Your Referral Link:'=>'Je doorverwijslink:','Your reviews:'=>'Jullie recensies:','Your reward is ready! Voucher code: {voucher_code}'=>'Je beloning is klaar! Vouchercode: {voucher_code}','Your voucher code is ready to use:'=>'Je vouchercode is klaar voor gebruik:','Your voucher has been claimed!'=>'Je voucher is geclaimd!','Your voucher has been successfully claimed.'=>'Je voucher is succesvol geclaimd.','Your voucher was applied automatically.'=>'Je voucher is automatisch toegepast.','Your voucher will be applied as soon as you add products to your cart.'=>'Je voucher wordt toegepast zodra je producten toevoegt aan je winkelwagen.','Your Vouchers'=>'Je vouchers','{points_label} Dashboard'=>'{punten_label} Dashboard','—'=>'-','— Select a page —'=>'- Selecteer een pagina -','← Previous'=>'← Vorige']];
